// Collect what the form sent: the uploaded images, the email address and the notes.
// The form stores each uploaded file in its own binary field, so we list those
// fields here and hand the list to the image reading step.
const item = $input.first();
const json = item.json || {};
const binary = item.binary || {};

const imageKeys = Object.keys(binary).filter((key) => {
  const mime = String(binary[key].mimeType || '').toLowerCase();
  return mime.startsWith('image/');
});

if (imageKeys.length === 0) {
  throw new Error('No image was received from the form. Please attach at least one image and try again.');
}

// Keep the images in the order they were attached (field_0, field_1, ...).
const trailingNumber = (key) => {
  const match = key.match(/_(\d+)$/);
  return match ? Number(match[1]) : 0;
};
imageKeys.sort((a, b) => trailingNumber(a) - trailingNumber(b) || a.localeCompare(b));

// Read a form answer by trying the possible field names.
const pick = (names) => {
  for (const name of names) {
    const value = json[name];
    if (value !== undefined && value !== null && String(value).trim() !== '') {
      return String(value).trim();
    }
  }
  return '';
};

const email = pick(['Email address', 'email', 'Email']);
const notes = pick(['Clinical notes and questions', 'notes', 'Notes']);

const fileNames = imageKeys.map((key) => binary[key].fileName || key);

return [{
  json: {
    binaryKeys: imageKeys.join(','),
    imageCount: imageKeys.length,
    fileNames,
    email,
    notes,
    submittedAt: json.submittedAt || new Date().toISOString(),
  },
  binary,
}];

// Pull the text Gemini produced (the node can return it in several shapes)
// and build the instructions for the reasoning model.
const partsToText = (parts) => (parts || []).map((p) => (p && typeof p.text === 'string') ? p.text : '').join('\n');

const readText = (data) => {
  if (!data) return '';
  if (typeof data === 'string') return data;
  if (typeof data.text === 'string') return data.text;
  if (typeof data.output === 'string') return data.output;
  if (data.content && Array.isArray(data.content.parts)) return partsToText(data.content.parts);
  if (Array.isArray(data.candidates)) {
    return data.candidates.map((c) => partsToText(c && c.content ? c.content.parts : [])).join('\n');
  }
  if (Array.isArray(data.parts)) return partsToText(data.parts);
  if (data.response) return readText(data.response);
  return JSON.stringify(data, null, 2);
};

const transcript = $input.all().map((item) => readText(item.json)).join('\n\n').trim();
if (!transcript) {
  throw new Error('The image reading step returned no text. Please check that the images are clear and try again.');
}

const form = $('Prepare images').first().json;
const notes = form.notes || '(none provided)';

const schema = `{
  "case_summary": "2 to 4 sentences summarising the patient and the key data.",
  "key_findings": ["Each abnormal or important finding as one short line, with the value and reference range where available."],
  "probable_diagnosis": {
    "name": "Single most likely diagnosis",
    "confidence_percent": 0,
    "rationale": "2 to 4 sentences: which findings support it and which argue against it."
  },
  "differential_diagnoses": [
    {
      "name": "Alternative diagnosis",
      "confidence_percent": 0,
      "rationale": "1 to 2 sentences on why it is considered.",
      "distinguishing_features": "1 sentence on what would confirm or exclude it."
    }
  ],
  "management_plan": {
    "immediate_actions": ["Steps needed now, including urgency and any escalation."],
    "investigations": ["Further tests, with a brief reason for each."],
    "treatment": ["Treatment options with usual adult doses where appropriate, or 'as per local guideline'."],
    "monitoring_and_follow_up": ["What to monitor, how often, and when to review."],
    "red_flags": ["Warning signs that need urgent reassessment."]
  },
  "data_gaps": ["Missing information or unreadable values that limit the assessment."]
}`;

const userPrompt = `You are an experienced hospital physician acting as a clinical decision support assistant for a qualified clinician. Use British English spelling and UK clinical conventions.

INPUT 1 - TRANSCRIPT OF THE UPLOADED IMAGES (extracted by an image reading model; [unclear] marks unreadable text):
<<<TRANSCRIPT
${transcript}
TRANSCRIPT>>>

INPUT 2 - NOTES AND QUESTIONS FROM THE CLINICIAN:
<<<NOTES
${notes}
NOTES>>>

YOUR TASK
1. Read every value in the transcript. Treat the reference ranges printed in the transcript as authoritative when present.
2. Formulate the single most probable diagnosis with a calibrated confidence percentage.
3. List 3 to 5 differential diagnoses, ordered from most to least likely, each with its own confidence percentage, a short rationale and the feature that would distinguish it. The probable diagnosis plus all differentials should add up to no more than 100 percent.
4. Write a management plan that a clinician can act on today.
5. Answer any specific question in the clinician's notes inside the relevant section.
6. Never invent values that are not in the transcript. If the data are insufficient for a confident diagnosis, say so in the rationale, keep the confidence low, and list what is missing under data_gaps.

OUTPUT FORMAT - STRICT
Return ONLY one JSON object, with no markdown fences and no text before or after it. Use exactly these keys and value types:
${schema}

Style rules for every string: plain professional English, short sentences, no emojis, no markdown, no bullet characters inside strings, and confidence_percent must be a whole number between 0 and 100.`;

return [{
  json: {
    userPrompt,
    transcript,
    email: form.email || '',
    notes: form.notes || '',
    imageCount: form.imageCount,
    fileNames: form.fileNames,
    binaryKeys: form.binaryKeys,
    submittedAt: form.submittedAt,
  },
}];

// Turn the reasoning model's JSON answer into an email with one fixed layout,
// so every report looks the same whatever the model wrote.
const DEFAULT_EMAIL = 'minthantthaw@gmail.com';
const REASONING_MODEL = 'deepseek-v4-pro';
const READING_MODEL = 'models/gemini-3.8-flash';

const answer = $input.first().json;
const context = $('Build clinical prompt').first().json;
const form = $('Prepare images').first();

// --- read the model output ------------------------------------------------
let raw = '';
if (typeof answer.text === 'string') raw = answer.text;
else if (typeof answer.output === 'string') raw = answer.output;
else if (answer.response && typeof answer.response.text === 'string') raw = answer.response.text;
else if (answer && typeof answer === 'object' && answer.probable_diagnosis) raw = JSON.stringify(answer);
else raw = JSON.stringify(answer);

const parseReport = (text) => {
  let cleaned = String(text).replace(/```(?:json)?/gi, '').trim();
  const first = cleaned.indexOf('{');
  const last = cleaned.lastIndexOf('}');
  if (first === -1 || last === -1) return null;
  cleaned = cleaned.slice(first, last + 1);
  try {
    return JSON.parse(cleaned);
  } catch (error) {
    return null;
  }
};

const report = parseReport(raw);

// --- small helpers ----------------------------------------------------------
const esc = (value) => String(value === undefined || value === null ? '' : value)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

const asList = (value) => {
  if (Array.isArray(value)) return value.map((v) => String(v)).filter((v) => v.trim() !== '');
  if (value === undefined || value === null || String(value).trim() === '') return [];
  return [String(value)];
};

const clampPercent = (value) => {
  const number = Math.round(Number(value));
  if (Number.isNaN(number)) return 0;
  return Math.max(0, Math.min(100, number));
};

const confidenceColour = (percent) => {
  if (percent >= 70) return '#1e8e5a';
  if (percent >= 40) return '#c98a00';
  return '#c2455a';
};

// --- fixed style tokens (kept in one place so the look never drifts) ----------
const FONT = "'Segoe UI Variable','Segoe UI',Roboto,Helvetica,Arial,sans-serif";
const NAVY = '#1b2140';
const NAVY_SOFT = '#4a5178';
const LINE = '#e3e6f2';
const BG = '#f4f5fb';
const ACCENT = '#5b5fe6';

const h2 = (title) => `<h2 style="margin:28px 0 10px;font-family:${FONT};font-size:17px;font-weight:700;color:${NAVY};letter-spacing:.2px;">${esc(title)}</h2>`;
const h3 = (title) => `<h3 style="margin:16px 0 6px;font-family:${FONT};font-size:14px;font-weight:700;color:${NAVY};">${esc(title)}</h3>`;
const p = (text) => `<p style="margin:0 0 10px;font-family:${FONT};font-size:14px;line-height:1.55;color:${NAVY};">${esc(text)}</p>`;
const ul = (items, emptyText) => {
  const list = asList(items);
  if (list.length === 0) return p(emptyText || 'None stated.');
  return `<ul style="margin:0 0 10px 0;padding-left:22px;">${list.map((item) => `<li style="margin:0 0 6px;font-family:${FONT};font-size:14px;line-height:1.5;color:${NAVY};">${esc(item)}</li>`).join('')}</ul>`;
};
const chip = (text, colour) => `<span style="display:inline-block;padding:4px 12px;border-radius:999px;background:${colour}1a;color:${colour};font-family:${FONT};font-size:13px;font-weight:700;">${esc(text)}</span>`;
const bar = (percent, colour) => `<table role="presentation" cellpadding="0" cellspacing="0" width="100%" style="margin:8px 0 0;"><tr><td style="background:${LINE};border-radius:6px;height:8px;"><div style="width:${percent}%;max-width:100%;height:8px;border-radius:6px;background:${colour};"></div></td></tr></table>`;

// --- build the body ---------------------------------------------------------
const submitted = new Date(context.submittedAt || Date.now());
const dateText = submitted.toLocaleString('en-GB', { dateStyle: 'long', timeStyle: 'short' });
const fileNames = asList(context.fileNames);

let body = '';
let probableName = '';

if (report && report.probable_diagnosis) {
  const probable = report.probable_diagnosis || {};
  const probablePercent = clampPercent(probable.confidence_percent);
  const probableColour = confidenceColour(probablePercent);
  probableName = String(probable.name || '').trim();
  const plan = report.management_plan || {};
  const differentials = Array.isArray(report.differential_diagnoses) ? report.differential_diagnoses : [];

  body += h2('1. Case summary');
  body += p(report.case_summary || 'No summary was produced.');

  body += h2('2. Key findings');
  body += ul(report.key_findings, 'No abnormal findings were listed.');

  body += h2('3. Probable diagnosis');
  body += `<table role="presentation" cellpadding="0" cellspacing="0" width="100%" style="border:1px solid ${LINE};border-radius:14px;background:#ffffff;"><tr><td style="padding:16px 18px;">`
    + `<div style="font-family:${FONT};font-size:18px;font-weight:700;color:${NAVY};margin-bottom:8px;">${esc(probableName || 'Not stated')}</div>`
    + chip(`${probablePercent}% confidence`, probableColour)
    + bar(probablePercent, probableColour)
    + `<div style="margin-top:12px;">${p(probable.rationale || 'No rationale was given.')}</div>`
    + `</td></tr></table>`;

  body += h2('4. Differential diagnoses');
  if (differentials.length === 0) {
    body += p('No differential diagnoses were listed.');
  } else {
    body += `<table cellpadding="0" cellspacing="0" width="100%" style="border-collapse:separate;border-spacing:0;border:1px solid ${LINE};border-radius:14px;overflow:hidden;background:#ffffff;">`
      + `<tr style="background:${BG};">`
      + `<th align="left" style="padding:10px 12px;font-family:${FONT};font-size:12.5px;font-weight:700;color:${NAVY_SOFT};text-transform:uppercase;letter-spacing:.4px;">Diagnosis</th>`
      + `<th align="left" style="padding:10px 12px;font-family:${FONT};font-size:12.5px;font-weight:700;color:${NAVY_SOFT};text-transform:uppercase;letter-spacing:.4px;white-space:nowrap;">Confidence</th>`
      + `<th align="left" style="padding:10px 12px;font-family:${FONT};font-size:12.5px;font-weight:700;color:${NAVY_SOFT};text-transform:uppercase;letter-spacing:.4px;">Why considered</th>`
      + `<th align="left" style="padding:10px 12px;font-family:${FONT};font-size:12.5px;font-weight:700;color:${NAVY_SOFT};text-transform:uppercase;letter-spacing:.4px;">How to confirm or exclude</th>`
      + `</tr>`;
    differentials.forEach((d, index) => {
      const percent = clampPercent(d.confidence_percent);
      const colour = confidenceColour(percent);
      const rowBg = index % 2 === 0 ? '#ffffff' : '#fafbfe';
      body += `<tr style="background:${rowBg};">`
        + `<td valign="top" style="padding:10px 12px;border-top:1px solid ${LINE};font-family:${FONT};font-size:14px;font-weight:700;color:${NAVY};">${esc(d.name || '')}</td>`
        + `<td valign="top" style="padding:10px 12px;border-top:1px solid ${LINE};white-space:nowrap;">${chip(`${percent}%`, colour)}</td>`
        + `<td valign="top" style="padding:10px 12px;border-top:1px solid ${LINE};font-family:${FONT};font-size:13.5px;line-height:1.5;color:${NAVY};">${esc(d.rationale || '')}</td>`
        + `<td valign="top" style="padding:10px 12px;border-top:1px solid ${LINE};font-family:${FONT};font-size:13.5px;line-height:1.5;color:${NAVY};">${esc(d.distinguishing_features || '')}</td>`
        + `</tr>`;
    });
    body += `</table>`;
  }

  body += h2('5. Management plan');
  body += h3('Immediate actions');
  body += ul(plan.immediate_actions);
  body += h3('Investigations');
  body += ul(plan.investigations);
  body += h3('Treatment');
  body += ul(plan.treatment);
  body += h3('Monitoring and follow-up');
  body += ul(plan.monitoring_and_follow_up);
  body += h3('Red flags');
  body += ul(plan.red_flags);

  body += h2('6. Data gaps and limitations');
  body += ul(report.data_gaps, 'No gaps were reported.');
} else {
  // The model did not return usable JSON: show its answer as written so nothing is lost.
  body += h2('Assessment');
  body += p('The reasoning model did not return its answer in the expected structure, so the full reply is shown below as written.');
  body += `<pre style="white-space:pre-wrap;word-wrap:break-word;margin:0;padding:14px 16px;border:1px solid ${LINE};border-radius:14px;background:#ffffff;font-family:${FONT};font-size:13.5px;line-height:1.5;color:${NAVY};">${esc(raw)}</pre>`;
}

body += h2('Clinician notes and questions');
body += p(context.notes && context.notes.trim() !== '' ? context.notes : 'No notes were entered.');

body += h2('Appendix: text read from the images');
body += p(`Read by ${READING_MODEL.replace('models/', '')} from ${context.imageCount} image(s)${fileNames.length ? ': ' + fileNames.join(', ') : ''}. The original images are attached to this email.`);
body += `<pre style="white-space:pre-wrap;word-wrap:break-word;margin:0;padding:14px 16px;border:1px solid ${LINE};border-radius:14px;background:#ffffff;font-family:'Cascadia Mono','Consolas','Courier New',monospace;font-size:12.5px;line-height:1.5;color:${NAVY};">${esc(context.transcript)}</pre>`;

const html = `<!DOCTYPE html>
<html lang="en">
<head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Clinical decision support report</title></head>
<body style="margin:0;padding:0;background:${BG};">
<table role="presentation" cellpadding="0" cellspacing="0" width="100%" style="background:${BG};padding:24px 12px;">
<tr><td align="center">
<table role="presentation" cellpadding="0" cellspacing="0" width="720" style="max-width:720px;width:100%;background:#ffffff;border:1px solid ${LINE};border-radius:20px;box-shadow:0 12px 32px rgba(27,33,64,0.08);">
<tr><td style="padding:26px 30px 18px;border-bottom:1px solid ${LINE};background:${ACCENT};background-image:linear-gradient(135deg,#7b61ff,#4f8dff);border-radius:20px 20px 0 0;">
  <div style="font-family:${FONT};font-size:12.5px;font-weight:600;color:#e9ecff;letter-spacing:.6px;text-transform:uppercase;">Clinical decision helper</div>
  <div style="font-family:${FONT};font-size:22px;font-weight:700;color:#ffffff;margin-top:6px;">Clinical decision support report</div>
  <div style="font-family:${FONT};font-size:13px;font-weight:500;color:#e9ecff;margin-top:6px;">${esc(dateText)} &nbsp;&middot;&nbsp; ${esc(String(context.imageCount))} image(s) reviewed</div>
</td></tr>
<tr><td style="padding:8px 30px 30px;">
${body}
</td></tr>
<tr><td style="padding:16px 30px 22px;border-top:1px solid ${LINE};background:${BG};border-radius:0 0 20px 20px;">
  <p style="margin:0;font-family:${FONT};font-size:12.5px;font-weight:500;line-height:1.5;color:${NAVY_SOFT};">This report was generated automatically to support, not replace, clinical judgement. It has not been reviewed by a clinician and may contain reading or reasoning errors. Verify every value against the original documents and follow local guidelines. Images read by ${esc(READING_MODEL.replace('models/', ''))}; reasoning by ${esc(REASONING_MODEL)}.</p>
</td></tr>
</table>
</td></tr>
</table>
</body>
</html>`;

// --- recipient and subject ----------------------------------------------------
const typedEmail = String(context.email || '').trim();
const looksLikeEmail = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(typedEmail);
const recipient = looksLikeEmail ? typedEmail : DEFAULT_EMAIL;

const subjectDate = submitted.toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' });
const subject = probableName
  ? `Clinical decision support report: ${probableName} (${subjectDate})`
  : `Clinical decision support report (${subjectDate})`;

return [{
  json: {
    recipient,
    subject,
    html,
    attachmentKeys: context.binaryKeys,
    probableDiagnosis: probableName,
    structuredReport: report,
  },
  binary: form.binary || {},
}];
